/*  _____ _______         _                      _
 * |_   _|__   __|       | |                    | |
 *   | |    | |_ __   ___| |___      _____  _ __| | __  ___ ____
 *   | |    | | '_ \ / _ \ __\ \ /\ / / _ \| '__| |/ / / __|_  /
 *  _| |_   | | | | |  __/ |_ \ V  V / (_) | |  |   < | (__ / /
 * |_____|  |_|_| |_|\___|\__| \_/\_/ \___/|_|  |_|\_(_)___/___|
 *                                _
 *              ___ ___ ___ _____|_|_ _ _____
 *             | . |  _| -_|     | | | |     |  LICENCE
 *             |  _|_| |___|_|_|_|_|___|_|_|_|
 *             |_|
 *
 *   PROGRAMOVÁNÍ  <>  DESIGN  <>  PRÁCE/PODNIKÁNÍ  <>  HW A SW
 *
 * Tento zdrojový kód je součástí výukových seriálů na
 * IT sociální síti WWW.ITNETWORK.CZ
 *
 * Kód spadá pod licenci prémiového obsahu a vznikl díky podpoře
 * našich členů. Je určen pouze pro osobní užití a nesmí být šířen.
 * Více informací na http://www.itnetwork.cz/licence
 */

import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useSession } from "../contexts/session";

const PersonTable = ({ label, items, deletePerson, filter }) => {
  const { session } = useSession();
  const isAdmin = session.data?.isAdmin === true;
  const [personList, setPersonList] = useState(items); // Přidání stavu pro položky

  const handleDelete = async (personId) => {
    try {
      // Volání funkce pro odstranění osoby (předpokládám, že je to asynchronní operace)
      const response = await deletePerson(personId);

      // Ověření, že odpověď byla v pořádku
      if (!response.ok) {
        throw new Error("Chyba při odstraňování osoby");
      }

      // Pokud je odpověď v pořádku, odstraníme osobu ze seznamu
      setPersonList((prevItems) => prevItems.filter((item) => item._id !== personId));
    } catch (error) {
      console.error("Došlo k chybě:", error);
    }
  };

  return (
    <div className="table-responsive">
      <hr />
      <table className="table table-hover table-bordered">
        <thead>
          <tr>
            <th>#</th>
            <th>Jméno</th>
            <th colSpan={3}>Akce</th>
          </tr>
        </thead>
        <tbody>
          {personList.map((item, index) => (
            <tr key={item._id}>
              <td>{(filter.page * filter.limit) + index + 1}</td>
              <td>{item.name}</td>
              <td>
                <div className="btn-group">
                  <Link to={"/persons/show/" + item._id} className="btn btn-sm btn-info">
                    Zobrazit
                  </Link>
                  {isAdmin ? (
                    <Link to={"/persons/edit/" + item._id} className="btn btn-sm btn-warning">
                      Upravit
                    </Link>
                  ) : null}
                  {isAdmin ? (
                    <button onClick={() => handleDelete(item._id)} className="btn btn-sm btn-danger">
                      Odstranit
                    </button>
                  ) : null}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default PersonTable;
